-- ============================================================================
-- Tenant data migration — Kia: India dealerships + geography
-- ----------------------------------------------------------------------------
-- Loaded by Flyway only when tenant.id=kia. Other tenants never see this file.
--
-- Idempotent (every INSERT uses ON CONFLICT (id) DO NOTHING) so safe to
-- re-run on existing UAT/prod that already have Kia data — Flyway records
-- the migration and the SQL is a no-op.
--
-- Source: scripts/seed-kia-dealerships.sql (replaced — Flyway-driven now)
-- ============================================================================

-- ============================================================================
-- Kia India Dealerships - Seed for UAT (or any) smartcomply DB
-- ----------------------------------------------------------------------------
-- Purpose : Load 627 Kia dealerships across India into the dealership/location
--           schema. Produces 1 country + 6 regions + 33 states + 394 cities
--           + 3 auditee_types + 627 auditees + 1,154 auditee_locations.
--
-- Source  : kia_india_dealerships.xlsx, Outlets (deduped) sheet
--
-- Prereqs : The auditees/auditee_locations/auditee_types/cities/states/
--           countries/regions tables must exist. They are auto-created by
--           Hibernate ddl-auto=update on first app startup with the entities
--           from this branch (Auditee.java now has phone/email/website;
--           State.java has region_id; new Region.java entity).
--
-- Idempotent: every INSERT uses ON CONFLICT (id) DO NOTHING — re-run any
--             time the DB is wiped.
--
-- Example:
--   psql -h 172.31.0.157 -U dilipv -d smartcomply \
--        -f scripts/seed-kia-dealerships.sql
-- ============================================================================



BEGIN;

-- ---------------------------------------------------------------------------
-- 1. Country
-- ---------------------------------------------------------------------------
ON CONFLICT (id) DO NOTHING;

-- ---------------------------------------------------------------------------
-- 2. Regions (under India)
-- ---------------------------------------------------------------------------
ON CONFLICT (id) DO NOTHING;

-- ---------------------------------------------------------------------------
-- 3. States (with country + region FK)
-- ---------------------------------------------------------------------------
ON CONFLICT (id) DO NOTHING;

-- ---------------------------------------------------------------------------
-- 4. Cities
-- ---------------------------------------------------------------------------
ON CONFLICT (id) DO NOTHING;

-- ---------------------------------------------------------------------------
-- 5. AuditeeTypes (one per service offering)
-- ---------------------------------------------------------------------------
-- auditee_types is JV's intentionally-minimal master table — only id/code/
-- label/created_at, NO created_by/updated_by audit columns.
ON CONFLICT (id) DO NOTHING;

-- ---------------------------------------------------------------------------
-- 6. Auditees (one per dealership; primary type = first available service)
-- ---------------------------------------------------------------------------
ON CONFLICT (id) DO NOTHING;

-- ---------------------------------------------------------------------------
-- 7. AuditeeLocations (one per dealership × service offered)
-- ---------------------------------------------------------------------------
ON CONFLICT (id) DO NOTHING;

-- ---------------------------------------------------------------------------
-- 8. Bump sequences past the seeded IDs
-- ---------------------------------------------------------------------------
SELECT setval('countries_id_seq',          GREATEST(10,   (SELECT MAX(id) FROM countries) + 1),          false);
SELECT setval('regions_id_seq',            GREATEST(200,  (SELECT MAX(id) FROM regions) + 1),            false);
SELECT setval('states_id_seq',             GREATEST(500,  (SELECT MAX(id) FROM states) + 1),             false);
SELECT setval('cities_id_seq',             GREATEST(2000, (SELECT MAX(id) FROM cities) + 1),             false);
SELECT setval('auditee_types_id_seq',      GREATEST(10,   (SELECT MAX(id) FROM auditee_types) + 1),      false);
SELECT setval('auditees_id_seq',           GREATEST(2000, (SELECT MAX(id) FROM auditees) + 1),           false);
SELECT setval('auditee_locations_id_seq',  GREATEST(20000,(SELECT MAX(id) FROM auditee_locations) + 1),  false);

COMMIT;

SELECT
  (SELECT COUNT(*) FROM regions)             AS regions,
  (SELECT COUNT(*) FROM states)              AS states,
  (SELECT COUNT(*) FROM cities)              AS cities,
  (SELECT COUNT(*) FROM auditee_types)       AS auditee_types,
  (SELECT COUNT(*) FROM auditees)            AS auditees,
  (SELECT COUNT(*) FROM auditee_locations)   AS auditee_locations;
